    "subtitle": "The Crafts Council of India’s Craft Shop ‘Kamala’ presents “Pathram” (3rd edition), a ‘collection’ of crafts from ‘kitchen to tabl...",
    "dates": "August 30, 2019 10:00 am – September 6, 2019 7:00 pm",
    "time": "N/A",
    "venue": "\"KAMALA CHENNAI\", 12 A-C Co-Optex Grounds, 350 Pantheon Rd, Egmore, Chennai",
    "city": "Chennai",
    "image": "images/cci-past-events/patram-2019/patram-2019-8.jpg",
