    "tagLabel": "Past Event",
    "tagClass": "past",
    "description": [
      "The Crafts Council of India’s Craft Shop ‘Kamala’ presents “Pathram” (3rd edition), a ‘collection’ of crafts from ‘kitchen to tableware’… celebrating the quintessential Indian pathram in all its evocative shapes, forms and colour, and it’s mystique of churning out the cornucopia of Indian dishes…as well as its evolution as part contemporary kitchen and table settings.",
      "Today, young and style centric generation wants trendy cookware and tableware, pathrams which are shaped for today’s lifestyle but rooted in traditional artisanal genius. CCI’s pathram collection offers a stunning and eye catching array of ‘kitchen to tableware’ with a look and flavour of the past yet tweaked, modified and even minimalized for everyday dining and for special occasions.  Alongside are dining table accessories such as exquisitely hand-crafted table mats, runners, tray, napkins and more.",
      "Pathrams at Kamala:",
      "✨ Bell metal Urlis from Kerala",
      "The classic urli traditionally used to make food for temple rituals is now a part of Kerala and other homes both as cooking vessel and as tableware",
      "✨ Kansa Katoris",
      "✨ Terracotta bowls, tumblers from Bhuj Gujarat",
      "✨ Soft stone Bowls  / Kalchattis from Salem",
      "✨ Miniature Jaipur Blue pottery",
      "✨ Eyyam: a wide range of Eyyam patram from kumbakonam",
      "✨ Ceramic Tableware",
      "✨ Contemporary Cutlery in Wood",
      "✨ Wood Spice with removable compartments and see-through lids.",
      "✨ Trays",
      "✨ Coasters",
      "✨ Runners",
      "Available at:",
      "“KAMALA”Crafts Shop of The Crafts Council of India12, A-C, Co Optex Grounds,350, Pantheon RoadEgmore, Chennai- 600 008",
      "Store Open Monday to Saturday10:30 am to 7:00 pm(Sunday Holiday)",
      "For enquiries on products call Shop Phone at:044-28191457‬",
      "Stay tuned to Kamala Chennai at:www.facebook.com/kamala.cciwww.instagram.com/kamala.cci"
    ],
