      "शिल्प में उत्कृष्टता के लिए कमला पुरस्कार वर्षों में किए गए कार्यों मेंप्रदर्शित एक शिल्पकार द्वारा प्राप्त उच्च स्तर की प्रवीणता और कौशलको मान्यता देता है। इस पुरस्कार में 10,000 / – रुपये, एक पदक, प्रमाण पत्र, उद्धरण और शाल का नकद पुरस्कार है।",
      "श्रेणी बी – शिल्प में योगदान के लिए कमला पुरस्कारशिल्प योगदान के लिए कमला अवॉर्ड अपने पारंपरिक शिल्प के विकासऔर क्षेत्र में युवा लोगों के प्रशिक्षण में उनके योगदान के लिए एक वरिष्ठकारीगर का सम्मान करता है। इस पुरस्कार में 10,000/ – रुपये, एकपदक, प्रमाण पत्र, उद्धरण और शाल का नकद पुरस्कार है।",
