    "id": "crafts-bazaar-2018",
    "source_link": "https://www.craftscouncilofindia.in/event/crafts-bazaar-2018/",
    "type": "event",
    "title": "Crafts Bazaar",
    "subtitle": "CRAFTS BAZAAR 2018| by The Crafts Council of IndiaA grand exposition showcasing the finest of craft from across India...",
    "dates": "January 2, 2018 10:00 am – 8, 2018 7:00 pm",
    "time": "N/A",
    "venue": "N/A",
    "city": "Chennai",
    "image": "images/cci-past-events/crafts-bazaar-2018/crafts-bazaar-2018-1.webp",
    "heroGradient": "linear-gradient(160deg,#7A8B60,#4A5830)",
    "heroEmoji": "🎨",
    "tagLabel": "Past Event",
    "tagClass": "past",
    "description": [
      "CRAFTS BAZAAR 2018| by The Crafts Council of IndiaA grand exposition showcasing the finest of craft from across India",
      "100 artisan exhibitors in Chennai for a weekStart Date: 2nd January 2018End Date: 8th January 2018Venue: Co-optex Grounds, No. 350, Pantheon Road, Egmore, ChennaiTiming: 10:30 am to 7:00 pm",
      "Exuberant colours and brilliant creativity, ancient hand craft skills and edgy innovation meet in a medley of dazzlingly diverse lifestyle products at “Crafts Bazaar 2018”, organised by The Crafts Council of India. 100 craft artisans converge at the Crafts Bazaar to display their fascinating and often unique handcrafts. Think weaves and you have a choice from heritage Patola saris and ikats to the earthy Bhujodi fabric, from exotic Bandhini saris and the fabled Mashroo to colourful Kutch embroidered made ups, Bagh saris and lots of handlooms for the art lover, Kerala’s mural art on wall hangings and home decor products ie with colour drenched Madhubani arts, the vibrant touch of Rajasthani’s Phad paintings and Gond art’s brilliant statements.",
      "‘Crafts Bazaar 2018’ rocks with cool eco-statements too. Sikki grass products, bamboo craft decorative and basketry, Kauna grass mats and bags and more, Punja dhurries, jute products, coconut shell, jewellery, jhoomars, terracotta products and pottery, natural fibre craft, paper craft and so much more. For the ecology buff there are saris embellished with of kora, sisal fibre, jute and palm leaf, embellished with folk art and not to be missed, outstanding vegetable dyed Ajrakh block prints on fabric stoles and dupattas.",
      "Wooden toys and earrings, Chennapatna toys for the children and the young at heart and bell metal vessels for the kitchen, terracotta jewellery and paper lamps, baskets and black pottery, tableware from Manipur, Narsapur lace and crochet make fascinatingly eclectic products statements at the Bazaar. Exquisite silver filigree products from Odisha are scene stealers as are tribal jewellery pieces and Kotpad saris. And you can feast your senses all at the Crafts Bazaar 2018 to the tripling sound of the copper camel bells of Kutch…….",
      "List of Artisans / participants:"
    ],
