    "type": "event",
    "title": "Khadi Week",
    "subtitle": "‘KHADI WEEK’ will be celebrated at CCI’s Crafts Shop KAMALA (Chennai) from Oct 3rd to 10th....",
    "dates": "October 3, 2017 10:30 am – 10, 2017 7:00 pm",
    "time": "N/A",
    "venue": "\"KAMALA CHENNAI\", 12 A-C Co-Optex Grounds, 350 Pantheon Rd, Egmore, Chennai",
    "city": "Chennai",
