      "The Crafts Council of India presents “Craftepreneur” – an exhibition of contemporary crafts – starting28th Octobertill31st October 2015at the Lalit Kala Academi, Chennai. The 4 day exhibition cum sale will showcase crafts, textiles, bags, jewellery, décor and home accents from 20 talented participants from across the country.",
      "“Crafteprenuer” is a phrase coined to represent an entrepreneur who has used a craft either current or languishing and has given it a contemporary twist. This exclusive show showcases the relevance of craft in modern times, without losing its inherent value. CCI recognizes the passion of these craftepreneurs and has amalgamated India’s handcrafted traditions in this show."
