    "id": "tnsdc_pattamadai",
    "source_link": "https://www.craftscouncilofindia.in/event/tnsdc_pattamadai/",
    "type": "event",
    "title": "TNSDC CCI Pattamadai skilling Programme",
    "subtitle": "The Government of Tamilnadu and The Crafts Council of India have joined forces to impart training to the Women Mat Weavers of Pattamadai at Tirunelveli. The programme is being designed by the Tamilnadu Skill ",
    "dates": "January 11 – February 28, 2021 ",
    "time": "9:00 am – 6:00 pm",
    "venue": "Pattamadai",
    "city": "Tirunnelveli",
    "image": "images/cci-past-events/tnsdc_pattamadai/tnsdc_pattamadai-1.jpg",
    "heroGradient": "linear-gradient(160deg,#7A8B60,#4A5830)",
    "heroEmoji": "🎨",
    "tagLabel": "Past Event",
    "tagClass": "past",
    "description": ["The Government of Tamilnadu and The Crafts Council of India have joined forces to impart training to the Women Mat Weavers of Pattamadai at Tirunelveli. The programme is being designed by the Tamilnadu Skill Development Centre (TNSDC) under SANKALP (Skills Acquisition and Knowledge Awareness for Livelihood Programme) funded by the Ministry of Skill Development and Entrepreneurship and World Bank.\n                      The 100 hours skilling programme implemented by The Crafts Council of India involves training in financial literacy, digital literacy, design interventions and tailoring. The training is being given to a group of forty women from the Lebbai community who are already familiar with pattamadai mat weaving.\n                      The District Collector, Tirunelveli Sri.V.Vishnu inaugurated the programme on 10th January 2021. He informed that a group called “Nellai Crafts” will be formed soon which would help in assisting artisans starting online sales. The programme commenced on 11th January 2021 and will run till 28th February 2021. A virtual exhibition will be organised at the end of the programme to showcase products made by the weavers."],
